/* global Office, window */

Office.onReady(() => {
  // If needed, Office.js is ready to be called.
});

const targetOrigin = process.env.ADDIN_URL;

/**
 * Shows a notification when the add-in command is executed.
 * @param event
 */
function action(event: Office.AddinCommands.Event) {
  const message: Office.NotificationMessageDetails = {
    type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
    message: "Performed action.",
    icon: "Icon.80x80",
    persistent: true,
  };

  // Show a notification message.
  Office.context.mailbox.item?.notificationMessages.replaceAsync(
    "ActionPerformanceNotification",
    message
  );

  // Be sure to indicate when the add-in command function is complete.
  event.completed();
}

type SafeRecipientsChangedEvent = Office.RecipientsChangedEventArgs & Office.MailboxEvent & {
  to?: boolean;
  cc?: boolean;
  bcc?: boolean;
};

/**
 * Shared logic to inspect fields, check for external domains, and update the Outlook UI.
 */
async function validateRecipientsAndUpdateUI(
  mailItem: Office.MessageCompose,
  checkTo: boolean,
  checkCc: boolean,
  checkBcc: boolean
): Promise<void> {
  const targetDomain = "@inMailX.onmicrosoft.com";
  let hasExternalRecipient = false;

  // 1. Inspect recipients concurrently for the flagged fields
  const promises: Promise<Office.EmailAddressDetails[] | null>[] = [
    checkTo ? getRecipientsAsync(mailItem.to) : Promise.resolve(null),
    checkCc ? getRecipientsAsync(mailItem.cc) : Promise.resolve(null),
    checkBcc ? getRecipientsAsync(mailItem.bcc) : Promise.resolve(null)
  ];

  const [toRecipients, ccRecipients, bccRecipients] = await Promise.all(promises);

  // 2. Evaluate if any verified recipient field contains an invalid domain
  if (
    (toRecipients && hasInvalidDomain(toRecipients, targetDomain)) ||
    (ccRecipients && hasInvalidDomain(ccRecipients, targetDomain)) ||
    (bccRecipients && hasInvalidDomain(bccRecipients, targetDomain))
  ) {
    hasExternalRecipient = true;
  }

  // 3. Update the Outlook notification UI securely using awaited Promises
  if (hasExternalRecipient) {
    await new Promise<void>((resolve) => {
      mailItem.notificationMessages.replaceAsync("ExternalDomainWarning", {
        type: Office.MailboxEnums.ItemNotificationMessageType.ErrorMessage,
        message: "Warning: Some or all recipients added to this message are external."
      }, () => resolve());
    });
  } else {
    // Remove the notification banner if all domains match or if the external user was removed
    await new Promise<void>((resolve) => {
      mailItem.notificationMessages.removeAsync("ExternalDomainWarning", () => resolve());
    });
  }
}

async function onMessageRecipientsChangedHandler(event: SafeRecipientsChangedEvent): Promise<void> {
  if (!event) return;

  try {
    const mailItem = Office.context.mailbox.item;

    if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    // Identify which fields changed using safe runtime checks
    const checkTo = event.changedRecipientFields ? event.changedRecipientFields.to : !!event.to;
    const checkCc = event.changedRecipientFields ? event.changedRecipientFields.cc : !!event.cc;
    const checkBcc = event.changedRecipientFields ? event.changedRecipientFields.bcc : !!event.bcc;

    // Execute the shared validation logic
    await validateRecipientsAndUpdateUI(mailItem, checkTo, checkCc, checkBcc);

  } catch (error) {
    console.error("Error processing recipient validation:", error);
  } finally {
    if (event && typeof event.completed === "function") {
      event.completed();
    }
  }
}

async function onNewMessageComposeHandler(event: Office.AddinCommands.Event): Promise<void> {
  if (!event) return;

  try {
    const mailItem = Office.context.mailbox.item;

    if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    // On initial compose startup, we must scan ALL fields to catch pre-populated recipients (Replies/Forwards)
    await validateRecipientsAndUpdateUI(mailItem, true, true, true);

  } catch (error) {
    console.error("Error during new message compose handling:", error);
  } finally {
    if (event && typeof event.completed === "function") {
    }
    event.completed();
  }
}

async function onMessageComposeHandler(event: Office.AddinCommands.Event): Promise<void> {
  if (!event) return;

  try {
    const mailItem = Office.context.mailbox.item;

    if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    // On initial compose startup, we must scan ALL fields to catch pre-populated recipients (Replies/Forwards)
    await validateRecipientsAndUpdateUI(mailItem, true, true, true);

  } catch (error) {
    console.error("Error during new message compose handling:", error);
  } finally {
    if (event && typeof event.completed === "function") {
    }
    event.completed();
  }
}

function getRecipientsAsync(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  return new Promise((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

function hasInvalidDomain(recipients: Office.EmailAddressDetails[], allowedDomain: string): boolean {
  return recipients.some(recipient => {
    const email = recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "";
    return email.length > 0 && !email.endsWith(allowedDomain.toLowerCase());
  });
}

// Register functions inside Office Action Management framework
Office.actions.associate("action", action);
Office.actions.associate("onMessageRecipientsChangedHandler", onMessageRecipientsChangedHandler);
Office.actions.associate("onNewMessageComposeHandler", onNewMessageComposeHandler);
Office.actions.associate("OnMessageCompose", onMessageComposeHandler);

// Expose functions explicitly to the Webpack window context for functional background executions
(window as any).action = action;
(window as any).onMessageRecipientsChangedHandler = onMessageRecipientsChangedHandler;
(window as any).onNewMessageComposeHandler = onNewMessageComposeHandler;
